package com.brightloop.quotation;
import com.brightloop.catalog.Product;import com.brightloop.catalog.ProductVariant;import com.brightloop.plan.Plan;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="quotation_lines") public class QuotationLine{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="quotation_id",nullable=false) Quotation quotation;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) Product product;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="plan_id") Plan plan;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="variant_id") ProductVariant variant;@Column(nullable=false) int quantity;@Column(name="unit_price",nullable=false,precision=12,scale=2) BigDecimal unitPrice;@Column(name="tax_rate",nullable=false,precision=12,scale=4) BigDecimal taxRate;@Column(name="line_subtotal",nullable=false,precision=14,scale=2) BigDecimal lineSubtotal;@Column(name="line_tax",nullable=false,precision=14,scale=2) BigDecimal lineTax;@Column(name="line_total",nullable=false,precision=14,scale=2) BigDecimal lineTotal;protected QuotationLine(){}public QuotationLine(Quotation q,Product p,Plan plan,ProductVariant variant,int qty,BigDecimal price,BigDecimal rate,BigDecimal subtotal,BigDecimal tax,BigDecimal total){quotation=q;product=p;this.plan=plan;this.variant=variant;quantity=qty;unitPrice=price;taxRate=rate;lineSubtotal=subtotal;lineTax=tax;lineTotal=total;}public Long getId(){return id;}public Product getProduct(){return product;}public Plan getPlan(){return plan;}public ProductVariant getVariant(){return variant;}public int getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getTaxRate(){return taxRate;}public BigDecimal getLineSubtotal(){return lineSubtotal;}public BigDecimal getLineTax(){return lineTax;}public BigDecimal getLineTotal(){return lineTotal;}}
